document.addEventListener("DOMContentLoaded",function(){var e=document.querySelectorAll('a[href^="/posts/"], a[href^="https://marioolf.github.io/posts/"]');e.forEach(function(e){var t,n=e.getAttribute("href");if(!n)return;if(t=new URL(n,window.location.origin),!t.pathname.startsWith("/posts/")||t.pathname==="/posts/"){e.removeAttribute("target"),e.removeAttribute("rel");return}e.setAttribute("target","_blank"),e.setAttribute("rel","noopener noreferrer")})})